/**
 * AgentRouter — multi-path agent dispatch.
 *
 * Routes coding subtasks across multiple agent backends in parallel:
 *   - claude     (Claude Code CLI — best for complex reasoning)
 *   - codex      (OpenAI Codex CLI — good for repo context)
 *   - gemini     (Google Gemini via ChainlessChain LLM provider)
 *   - openai     (GPT-4o via ChainlessChain LLM provider)
 *   - ollama     (Local LLM — offline / private)
 *
 * Routing strategies:
 *   round-robin  — distribute evenly across available backends
 *   by-type      — route based on task type keywords
 *   parallel-all — every subtask runs on ALL backends; pick best result
 *   primary      — use first available backend, others as fallback
 *
 * Usage:
 *   const router = new AgentRouter({
 *     backends: [
 *       { type: "claude", weight: 2 },
 *       { type: "gemini", apiKey: "...", model: "gemini-1.5-pro", weight: 1 },
 *     ],
 *     strategy: "round-robin",
 *   });
 *   const results = await router.dispatch(subtasks, {
 *     cwd: "/my/project",
 *     evolutionIngress,
 *   });
 */

import { EventEmitter } from "events";
import {
  ClaudeCodePool,
  detectClaudeCode,
  detectCodex,
} from "./claude-code-bridge.js";
import { createChatFn } from "./cowork-adapter.js";
import { captureAgentEvolutionIngress } from "./evolution/agent-evolution-ingress.js";
import { isTerminalModelFailure } from "./model-failure-policy.js";
import runtimeClaimsContract from "@chainlesschain/session-core/runtime-claims";

const { RUNTIME_MODE, createRuntimeClaims } = runtimeClaimsContract;
const SIMULATED_API_CLAIMS = createRuntimeClaims({
  mode: RUNTIME_MODE.SIMULATED,
});

// ─── Backend type constants ───────────────────────────────────────
export const BACKEND_TYPE = {
  CLAUDE: "claude",
  CODEX: "codex",
  GEMINI: "gemini",
  OPENAI: "openai",
  ANTHROPIC: "anthropic",
  OLLAMA: "ollama",
};

// ─── Task type → preferred backend mapping ────────────────────────
const TASK_TYPE_ROUTING = {
  "code-generation": BACKEND_TYPE.CLAUDE,
  "code-review": BACKEND_TYPE.CLAUDE,
  testing: BACKEND_TYPE.CLAUDE,
  documentation: BACKEND_TYPE.OPENAI,
  "data-analysis": BACKEND_TYPE.GEMINI,
  research: BACKEND_TYPE.GEMINI,
};

// Keywords for auto-detecting task type
const TYPE_KEYWORDS = {
  "code-generation": [
    "implement",
    "create",
    "build",
    "add feature",
    "fix",
    "refactor",
  ],
  "code-review": ["review", "audit", "check", "inspect", "analyze"],
  testing: ["test", "spec", "unit test", "e2e", "coverage"],
  documentation: ["document", "readme", "comment", "docstring", "explain"],
  "data-analysis": ["data", "analyze", "statistics", "report", "chart"],
  research: ["research", "investigate", "explore", "compare"],
};

export const AGENT_ROUTER_ERROR = Object.freeze({
  WRITE_ISOLATION_REQUIRED: "AGENT_ROUTER_WRITE_ISOLATION_REQUIRED",
  EXTERNAL_MODEL_INGRESS_UNATTESTED:
    "AGENT_ROUTER_EXTERNAL_MODEL_INGRESS_UNATTESTED",
});

function normalizedScopes(task) {
  if (!Array.isArray(task?.scopePaths) || task.scopePaths.length === 0) {
    return null;
  }
  return task.scopePaths.map(
    (scope) => String(scope).replace(/\\/g, "/").replace(/\/+$/u, "") + "/",
  );
}

export function assignmentsHaveDisjointWrites(assignments) {
  if (assignments.every(({ task }) => task?.effects === "read-only")) {
    return true;
  }
  const scopes = assignments.map(({ task }) => normalizedScopes(task));
  if (scopes.some((scope) => scope === null)) return false;
  for (let i = 0; i < scopes.length; i += 1) {
    for (let j = i + 1; j < scopes.length; j += 1) {
      for (const left of scopes[i]) {
        for (const right of scopes[j]) {
          if (left.startsWith(right) || right.startsWith(left)) return false;
        }
      }
    }
  }
  return true;
}

function detectTaskType(description) {
  const lower = description.toLowerCase();
  for (const [type, keywords] of Object.entries(TYPE_KEYWORDS)) {
    if (keywords.some((kw) => lower.includes(kw))) return type;
  }
  return "code-generation";
}

// ─── API-based agent executor ─────────────────────────────────────

/**
 * Execute a task using an LLM API backend (Gemini, GPT, Ollama, etc.)
 * through ChainlessChain's existing llm-providers infrastructure.
 */
async function executeViaAPI(task, options) {
  const {
    provider,
    model,
    apiKey,
    baseUrl,
    cwd,
    timeout = 120_000,
    evolutionIngress = null,
  } = options;

  const chat = createChatFn({
    provider,
    model,
    apiKey,
    baseUrl,
    ...(evolutionIngress === null ? {} : { evolutionIngress }),
  });

  const systemPrompt =
    "You are an expert software engineer. Implement the requested changes precisely. " +
    "Respond with the complete implementation, file paths, and explanations. " +
    `Working directory: ${cwd}`;

  const startTime = Date.now();
  let timeoutHandle;
  try {
    const timeoutPromise = new Promise((_, reject) => {
      timeoutHandle = setTimeout(
        () => reject(new Error("LLM API timeout")),
        timeout,
      );
    });
    const output = await Promise.race([
      chat(
        [
          { role: "system", content: systemPrompt },
          {
            role: "user",
            content: task.context
              ? `Context:\n${task.context}\n\nTask:\n${task.description}`
              : task.description,
          },
        ],
        { maxTokens: 4096 },
      ),
      timeoutPromise,
    ]);

    return {
      success: false,
      status: "simulated",
      output,
      exitCode: 0,
      duration: Date.now() - startTime,
      agentId: `api-${provider}`,
      runtimeClaims: SIMULATED_API_CLAIMS,
      terminalEvidence: [],
    };
  } catch (err) {
    if (isTerminalModelFailure(err)) throw err;
    return {
      success: false,
      status: "failed",
      output: "",
      exitCode: -1,
      duration: Date.now() - startTime,
      agentId: `api-${provider}`,
      error: err.message,
      runtimeClaims: SIMULATED_API_CLAIMS,
      terminalEvidence: [],
    };
  } finally {
    clearTimeout(timeoutHandle);
  }
}

// ─── AgentRouter ──────────────────────────────────────────────────

export class AgentRouter extends EventEmitter {
  /**
   * @param {object} options
   * @param {Array}   options.backends   - Backend configs (see examples above)
   * @param {string}  options.strategy   - "round-robin"|"by-type"|"parallel-all"|"primary"
   * @param {number}  options.maxParallel - Max concurrent agent tasks (default 3)
   */
  constructor(options = {}) {
    super();
    this.strategy = options.strategy || "round-robin";
    this.maxParallel = options.maxParallel || 3;
    this._backends = this._resolveBackends(options.backends || []);
    this._rrIndex = 0; // round-robin cursor
  }

  /**
   * Auto-detect available backends from the environment.
   * Includes CLI tools and API providers based on env vars.
   */
  static autoDetect(options = {}) {
    const backends = [];
    const claude = options.cliDetections?.claude || detectClaudeCode();
    const codex = options.cliDetections?.codex || detectCodex();

    if (claude.found) {
      backends.push({ type: BACKEND_TYPE.CLAUDE, weight: 3, installed: true });
    }
    if (codex.found) {
      backends.push({ type: BACKEND_TYPE.CODEX, weight: 2, installed: true });
    }
    if (process.env.GEMINI_API_KEY) {
      backends.push({ type: BACKEND_TYPE.GEMINI, weight: 2 });
    }
    if (process.env.OPENAI_API_KEY) {
      backends.push({ type: BACKEND_TYPE.OPENAI, weight: 2 });
    }
    if (process.env.ANTHROPIC_API_KEY) {
      backends.push({ type: BACKEND_TYPE.ANTHROPIC, weight: 2 });
    }
    // Always include Ollama as local fallback
    backends.push({ type: BACKEND_TYPE.OLLAMA, weight: 1 });

    return new AgentRouter({ ...options, backends });
  }

  /**
   * Dispatch subtasks to agent backends according to the routing strategy.
   *
   * @param {Array<{id, description, context?, type?}>} subtasks
   * @param {object} options
   * @param {string} options.cwd
   * @param {object} options.evolutionIngress authenticated model ingress
   * @returns {Promise<Array<{taskId, agentId, backendType, success, output, duration}>>}
   */
  async dispatch(subtasks, options = {}) {
    const { cwd = process.cwd() } = options;
    if (this._backends.length === 0) {
      throw new Error(
        "No agent backends available. Use cc agent for tool execution; orchestrate API backends produce text only.",
      );
    }
    const evolutionIngress =
      options.evolutionIngress == null
        ? null
        : captureAgentEvolutionIngress(options.evolutionIngress);
    if (evolutionIngress === null) {
      const error = new Error(
        "AgentRouter model dispatch requires an authenticated evolution composition",
      );
      error.code = "CC_AGENT_EVOLUTION_INGRESS_FAILED";
      throw error;
    }
    const backends = this._backends.filter((backend) => !backend.isCLI);

    if (backends.length === 0) {
      const error = new Error(
        "No backend can attest per-request evolution ingress; external agent CLIs are opaque",
      );
      error.code = AGENT_ROUTER_ERROR.EXTERNAL_MODEL_INGRESS_UNATTESTED;
      throw error;
    }

    switch (this.strategy) {
      case "parallel-all":
        return this._dispatchParallelAll(subtasks, {
          cwd,
          evolutionIngress,
          backends,
        });
      case "by-type":
        return this._dispatchByType(subtasks, {
          cwd,
          evolutionIngress,
          backends,
        });
      case "primary":
        return this._dispatchPrimary(subtasks, {
          cwd,
          evolutionIngress,
          backends,
        });
      default: // round-robin
        return this._dispatchRoundRobin(subtasks, {
          cwd,
          evolutionIngress,
          backends,
        });
    }
  }

  // ─── Strategies ────────────────────────────────────────────────

  /** Round-robin: distribute tasks evenly across all backends. */
  async _dispatchRoundRobin(subtasks, { cwd, evolutionIngress, backends }) {
    // Assign each subtask a backend
    const assignments = subtasks.map((task) => {
      const backend = this._weightedNext(backends);
      return { task, backend };
    });

    return this._runAssignments(assignments, { cwd, evolutionIngress });
  }

  /** By-type: route task to the best backend for its type. */
  async _dispatchByType(subtasks, { cwd, evolutionIngress, backends }) {
    const assignments = subtasks.map((task) => {
      const taskType = task.type || detectTaskType(task.description);
      const preferredType = TASK_TYPE_ROUTING[taskType];
      const backend =
        this._findBackend(preferredType, backends) ||
        this._weightedNext(backends);
      return { task, backend };
    });

    return this._runAssignments(assignments, { cwd, evolutionIngress });
  }

  /** Primary: all tasks go to first backend; fallback on failure. */
  async _dispatchPrimary(subtasks, { cwd, evolutionIngress, backends }) {
    const primary = backends[0];
    const assignments = subtasks.map((task) => ({ task, backend: primary }));
    const results = await this._runAssignments(assignments, {
      cwd,
      evolutionIngress,
    });

    // Retry failed tasks on next available backend
    const retries = [];
    for (let i = 0; i < results.length; i++) {
      if (!results[i].success && backends.length > 1) {
        const fallback = backends[1];
        retries.push(
          this._runSingleTask(subtasks[i], fallback, {
            cwd,
            evolutionIngress,
          }).then((r) => {
            results[i] = r;
          }),
        );
      }
    }
    await Promise.all(retries);
    return results;
  }

  /** Parallel-all: run every task on ALL backends; return best result per task. */
  async _dispatchParallelAll(subtasks, { cwd, evolutionIngress, backends }) {
    if (backends.length > 1) {
      const error = new Error(
        "parallel-all requires per-attempt worktrees and accepted-winner merge",
      );
      error.code = AGENT_ROUTER_ERROR.WRITE_ISOLATION_REQUIRED;
      throw error;
    }
    const results = [];
    for (const task of subtasks) {
      const allResults = await Promise.all(
        backends.map((backend) =>
          this._runSingleTask(task, backend, { cwd, evolutionIngress }),
        ),
      );
      // Pick the first successful result; if all fail, pick the first
      const best = allResults.find((r) => r.success) || allResults[0];
      best.allResults = allResults; // attach all results for inspection
      results.push(best);
    }
    return results;
  }

  // ─── Execution ─────────────────────────────────────────────────

  async _runAssignments(assignments, { cwd, evolutionIngress }) {
    const results = new Array(assignments.length);
    const concurrency = assignmentsHaveDisjointWrites(assignments)
      ? this.maxParallel
      : 1;

    // Shared writable cwd tasks are serialized unless their declared write
    // scopes are statically disjoint. Candidate fan-out is rejected above
    // until it has per-attempt worktrees and winner-only merge semantics.
    for (let i = 0; i < assignments.length; i += concurrency) {
      const batch = assignments.slice(i, i + concurrency);
      const batchResults = await Promise.all(
        batch.map(({ task, backend }) =>
          this._runSingleTask(task, backend, { cwd, evolutionIngress }),
        ),
      );
      for (let j = 0; j < batchResults.length; j++) {
        results[i + j] = batchResults[j];
      }
    }

    return results;
  }

  async _runSingleTask(task, backend, { cwd, evolutionIngress }) {
    this.emit("agent:start", { taskId: task.id, backend: backend.type });

    let result;
    if (backend.isCLI) {
      // Claude/Codex own every provider call made inside their subprocess. A
      // projected initial prompt cannot prove that later compaction, retry,
      // tool, or model calls crossed this Run's durable ingress. Until an
      // authenticated child protocol can bind every such call and return
      // evidence, admitting the black box would create an unobservable model
      // bypass. This is deliberately unconditional so a future internal caller
      // cannot bypass dispatch()'s candidate filter by calling this helper.
      const error = new Error(
        `External ${backend.type} CLI does not attest per-request evolution ingress`,
      );
      error.code = AGENT_ROUTER_ERROR.EXTERNAL_MODEL_INGRESS_UNATTESTED;
      throw error;
    } else {
      // Use LLM API for API-based backends
      result = await executeViaAPI(task, {
        provider: backend.provider,
        model: backend.model,
        apiKey: backend.apiKey,
        baseUrl: backend.baseUrl,
        cwd,
        timeout: backend.timeout,
        evolutionIngress,
      });
    }

    result.taskId = task.id;
    result.backendType = backend.type;

    this.emit("agent:complete", result);
    return result;
  }

  // ─── Backend resolution ─────────────────────────────────────────

  _resolveBackends(configs) {
    return configs.map((cfg) => {
      const type = cfg.type || BACKEND_TYPE.CLAUDE;

      if (type === BACKEND_TYPE.CLAUDE || type === BACKEND_TYPE.CODEX) {
        const pool = new ClaudeCodePool({
          maxParallel: 1,
          cliCommand: type === BACKEND_TYPE.CODEX ? "codex" : "claude",
          model: cfg.model || null,
          sandbox: cfg.sandbox || null,
        });
        pool.on("agent:output", (ev) => this.emit("agent:output", ev));
        return {
          type,
          isCLI: true,
          installed: cfg.installed ?? null,
          weight: cfg.weight || 1,
          _pool: pool,
          timeout: cfg.timeout || 300_000,
        };
      }

      // API-based backend
      const providerMap = {
        [BACKEND_TYPE.GEMINI]: "gemini",
        [BACKEND_TYPE.OPENAI]: "openai",
        [BACKEND_TYPE.ANTHROPIC]: "anthropic",
        [BACKEND_TYPE.OLLAMA]: "ollama",
      };

      return {
        type,
        isCLI: false,
        weight: cfg.weight || 1,
        provider: providerMap[type] || type,
        model: cfg.model || null,
        apiKey: cfg.apiKey || null,
        baseUrl: cfg.baseUrl || null,
        timeout: cfg.timeout || 120_000,
      };
    });
  }

  /** Find the first backend matching a given type. */
  _findBackend(type, backends = this._backends) {
    return backends.find((b) => b.type === type) || null;
  }

  /** Pick next backend using weighted round-robin. */
  _weightedNext(backends = this._backends) {
    if (backends.length === 0) throw new Error("No backends");
    if (backends.length === 1) return backends[0];

    // Build weighted list
    const weighted = [];
    for (const b of backends) {
      for (let i = 0; i < (b.weight || 1); i++) weighted.push(b);
    }

    const backend = weighted[this._rrIndex % weighted.length];
    this._rrIndex++;
    return backend;
  }

  /** Summary of all configured backends. */
  summary() {
    return this._backends.map((b) => ({
      type: b.type,
      kind: b.isCLI ? "cli" : "api",
      provider: b.provider || b.type,
      weight: b.weight,
      installed: b.isCLI ? (b.installed ?? null) : null,
      configured: true,
      governanceAdmitted: b.isCLI ? false : null,
      requiresAuthenticatedRun: true,
      dispatchable: !b.isCLI,
      runnable: false,
      executionMode: b.isCLI ? "blocked" : "text-only",
      blockedReason: b.isCLI
        ? AGENT_ROUTER_ERROR.EXTERNAL_MODEL_INGRESS_UNATTESTED
        : "API_TEXT_ONLY_NO_TOOL_EXECUTION",
      alternative: "cc agent",
    }));
  }

  /** Configuration preflight only; dispatch still authenticates each Run. */
  assertDispatchAvailable() {
    if (this._backends.some((backend) => !backend.isCLI)) return;
    const error = new Error(
      this._backends.length
        ? "External Claude/Codex CLIs are blocked: per-request model governance is unattested. Use cc agent for tool execution."
        : "No agent backends available. Use cc agent for tool execution.",
    );
    error.code = this._backends.length
      ? AGENT_ROUTER_ERROR.EXTERNAL_MODEL_INGRESS_UNATTESTED
      : "AGENT_ROUTER_NO_BACKENDS";
    error.backends = this.summary();
    throw error;
  }
}

// ===== V2 Surface: Agent Router governance overlay (CLI v0.132.0) =====
// In-memory governance for router profiles + dispatch lifecycle, independent of
// the AgentRouter class above (legacy ClaudeCodePool/createChatFn untouched).

export const ROUTER_PROFILE_MATURITY_V2 = Object.freeze({
  PENDING: "pending",
  ACTIVE: "active",
  DEGRADED: "degraded",
  RETIRED: "retired",
});

export const ROUTER_DISPATCH_LIFECYCLE_V2 = Object.freeze({
  QUEUED: "queued",
  DISPATCHING: "dispatching",
  COMPLETED: "completed",
  FAILED: "failed",
  CANCELLED: "cancelled",
});

const _profileTransitionsV2 = new Map([
  [
    ROUTER_PROFILE_MATURITY_V2.PENDING,
    new Set([
      ROUTER_PROFILE_MATURITY_V2.ACTIVE,
      ROUTER_PROFILE_MATURITY_V2.RETIRED,
    ]),
  ],
  [
    ROUTER_PROFILE_MATURITY_V2.ACTIVE,
    new Set([
      ROUTER_PROFILE_MATURITY_V2.DEGRADED,
      ROUTER_PROFILE_MATURITY_V2.RETIRED,
    ]),
  ],
  [
    ROUTER_PROFILE_MATURITY_V2.DEGRADED,
    new Set([
      ROUTER_PROFILE_MATURITY_V2.ACTIVE,
      ROUTER_PROFILE_MATURITY_V2.RETIRED,
    ]),
  ],
  [ROUTER_PROFILE_MATURITY_V2.RETIRED, new Set()],
]);
const _profileTerminalV2 = new Set([ROUTER_PROFILE_MATURITY_V2.RETIRED]);

const _dispatchTransitionsV2 = new Map([
  [
    ROUTER_DISPATCH_LIFECYCLE_V2.QUEUED,
    new Set([
      ROUTER_DISPATCH_LIFECYCLE_V2.DISPATCHING,
      ROUTER_DISPATCH_LIFECYCLE_V2.CANCELLED,
    ]),
  ],
  [
    ROUTER_DISPATCH_LIFECYCLE_V2.DISPATCHING,
    new Set([
