      d.status = ROUTER_DISPATCH_LIFECYCLE_V2.FAILED;
      d.updatedAt = t;
      if (!d.settledAt) d.settledAt = t;
      d.metadata.failReason = "auto-fail-stuck";
      flipped.push(d.id);
