    throw error;
  }

  switch (this.strategy) {
    case "parallel-all":
      return this._dispatchParallelAll(subtasks, {
        cwd,
        evolutionIngress,
        backends,
      });
    case "by-type":
      return this._dispatchByType(subtasks, {
        cwd,
        evolutionIngress,
        backends,
      });
    case "primary":
      return this._dispatchPrimary(subtasks, {
        cwd,
        evolutionIngress,
        backends,
      });
    default: // round-robin
      return this._dispatchRoundRobin(subtasks, {
        cwd,
        evolutionIngress,
        backends,
      });
