    const cli = makeInstalledCliBackend();
    const router = makeRouter([cli]);
    // Negative control: even though the CLI is installed, a direct run attempt is
    // refused on attestation grounds, and its pool is never started.
    await expect(
      router._runSingleTask({ id: "t1", description: "task" }, cli, {
        cwd: "/tmp",
        evolutionIngress: null,
      }),
    ).rejects.toMatchObject({
      code: AGENT_ROUTER_ERROR.EXTERNAL_MODEL_INGRESS_UNATTESTED,
    });
    expect(cli._pool.dispatch).not.toHaveBeenCalled();
  });

  it("C5: assertDispatchAvailable refuses when no backends exist", () => {
    const router = makeRouter([]);
    expect(() => router.assertDispatchAvailable()).toThrowError(
      "AGENT_ROUTER_NO_BACKENDS",
    );
  });
});

    // scopes are statically disjoint. Candidate fan-out is rejected above
    // until it has per-attempt worktrees and winner-only merge semantics.
    for (let i = 0; i < assignments.length; i += concurrency) {
      const batch = assignments.slice(i, i + concurrency);
      const batchResults = await Promise.all(
        batch.map(({ task, backend }) =>
          this._runSingleTask(task, backend, { cwd, evolutionIngress }),
        ),
      );
      for (let j = 0; j < batchResults.length; j++) {
        results[i + j] = batchResults[j];
      }
    }

    return results;
  }

  async _runSingleTask(task, backend, { cwd, evolutionIngress }) {
    this.emit("agent:start", { taskId: task.id, backend: backend.type });

    let result;
    if (backend.isCLI) {
      // Claude/Codex own every provider call made inside their subprocess. A
      // projected initial prompt cannot prove that later compaction, retry,
      // tool, or model calls crossed this Run's durable ingress. Until an
      // authenticated child protocol can bind every such call and return
      // evidence, admitting the black box would create an unobservable model
      // bypass. This is deliberately unconditional so a future internal caller
      // cannot bypass dispatch()'s candidate filter by calling this helper.
      const error = new Error(
        `External ${backend.type} CLI does not attest per-request evolution ingress`,
      );
      error.code = AGENT_ROUTER_ERROR.EXTERNAL_MODEL_INGRESS_UNATTESTED;
      throw error;
    } else {
      // Use LLM API for API-based backends
      result = await executeViaAPI(task, {
        provider: backend.provider,
        model: backend.model,
        apiKey: backend.apiKey,
        baseUrl: backend.baseUrl,
        cwd,
        timeout: backend.timeout,
        evolutionIngress,
      });
    }

    result.taskId = task.id;
    result.backendType = backend.type;

    this.emit("agent:complete", result);
    return result;
  }

  // ─── Backend resolution ─────────────────────────────────────────

  _resolveBackends(configs) {
    return configs.map((cfg) => {
      const type = cfg.type || BACKEND_TYPE.CLAUDE;

      if (type === BACKEND_TYPE.CLAUDE || type === BACKEND_TYPE.CODEX) {
        const pool = new ClaudeCodePool({
          maxParallel: 1,
          cliCommand: type === BACKEND_TYPE.CODEX ? "codex" : "claude",
          model: cfg.model || null,
          sandbox: cfg.sandbox || null,
        });
        pool.on("agent:output", (ev) => this.emit("agent:output", ev));
        return {
          type,
          isCLI: true,
          installed: cfg.installed ?? null,
          weight: cfg.weight || 1,
          _pool: pool,
          timeout: cfg.timeout || 300_000,
        };
      }

      // API-based backend
      const providerMap = {
        [BACKEND_TYPE.GEMINI]: "gemini",
        [BACKEND_TYPE.OPENAI]: "openai",
        [BACKEND_TYPE.ANTHROPIC]: "anthropic",
        [BACKEND_TYPE.OLLAMA]: "ollama",
      };

      return {
        type,
        isCLI: false,
        weight: cfg.weight || 1,
        provider: providerMap[type] || type,
        model: cfg.model || null,
        apiKey: cfg.apiKey || null,
        baseUrl: cfg.baseUrl || null,
        timeout: cfg.timeout || 120_000,
      };
    });
  }

  /** Find the first backend matching a given type. */
  _findBackend(type, backends = this._backends) {
    return backends.find((b) => b.type === type) || null;
  }

  /** Pick next backend using weighted round-robin. */
  _weightedNext(backends = this._backends) {
    if (backends.length === 0) throw new Error("No backends");
    if (backends.length === 1) return backends[0];

    // Build weighted list
    const weighted = [];
    for (const b of backends) {
      for (let i = 0; i < (b.weight || 1); i++) weighted.push(b);
    }

    const backend = weighted[this._rrIndex % weighted.length];
    this._rrIndex++;
    return backend;
  }

  /** Summary of all configured backends. */
  summary() {
    return this._backends.map((b) => ({
      type: b.type,
      kind: b.isCLI ? "cli" : "api",
      provider: b.provider || b.type,
      weight: b.weight,
      installed: b.isCLI ? (b.installed ?? null) : null,
      configured: true,
      governanceAdmitted: b.isCLI ? false : null,
      requiresAuthenticatedRun: true,
      dispatchable: !b.isCLI,
      runnable: false,
      executionMode: b.isCLI ? "blocked" : "text-only",
      blockedReason: b.isCLI
        ? AGENT_ROUTER_ERROR.EXTERNAL_MODEL_INGRESS_UNATTESTED
        : "API_TEXT_ONLY_NO_TOOL_EXECUTION",
      alternative: "cc agent",
    }));
  }

  /** Configuration preflight only; dispatch still authenticates each Run. */
  assertDispatchAvailable() {
    if (this._backends.some((backend) => !backend.isCLI)) return;
    const error = new Error(
      this._backends.length
        ? "External Claude/Codex CLIs are blocked: per-request model governance is unattested. Use cc agent for tool execution."
        : "No agent backends available. Use cc agent for tool execution.",
    );
    error.code = this._backends.length
      ? AGENT_ROUTER_ERROR.EXTERNAL_MODEL_INGRESS_UNATTESTED
      : "AGENT_ROUTER_NO_BACKENDS";
    error.backends = this.summary();
    throw error;
  }
}

